import assert from 'node:assert/strict';
import fs from 'node:fs';
const read=p=>fs.readFileSync(p,'utf8');
const route=read('app/api/customer-block-check/route.ts');
const guard=read('components/customer/CustomerAccessBlockGuard.tsx');
const admin=read('components/admin-live/AdminLiveCustomerBlockReasonModal.tsx');
const reason=read('lib/customerBlockReason.ts');
assert.match(route,/verifyChatIdentity\(request\.cookies\.get\(CHAT_SESSION_COOKIE\)/,'signed HttpOnly Kakao cookie verified server-side');
assert.match(route,/canExposeBlockDetails\(phone,verified,rows\)/,'server-verified phone ownership checked');
assert.match(route,/details=mayView\?publicBlockDetails\(reason,registeredAt\):null/,'private details gated');
assert.doesNotMatch(route,/reason:\s*reason\b/,'never return raw reason');
assert.match(route,/Cache-Control.?:.?'private, no-store'/,'no caching private block metadata');
assert.match(guard,/role="alertdialog" aria-modal="true"/,'accessible focused notice');
assert.match(guard,/d\.dealDate\|\|'기록 없음 · 문의 필요'/,'unrecorded incident date is not invented');
assert.match(guard,/won\(it\.amount\)/,'product amounts visibly displayed');
assert.match(guard,/ShopContactLink/,'shop-configured Kakao contact');
assert.match(guard,/다른 계정으로 로그인/,'user can use another Kakao account');
assert.match(admin,/id="deal-break-date" type="date"/,'admin can register actual incident date');
assert.match(reason,/input\.type === "deal_break" \? validDealDate\(input\.dealDate\)/,'date only applies to deal breaks');
assert.doesNotMatch(guard,/\.memo\b/,'freeform internal notes are never displayed');
console.log('PASS customer block contract: identity, privacy, date accuracy, Apple-like UI, Kakao contact');
